phase.example:
function: "() => {
  const elements = document.querySelectorAll('h1, h2, h3, p, a, button, .card, .badge');
  return Array.from(elements).slice(0, 50).map(el => {
    const s = getComputedStyle(el);
    return {
      tag: el.tagName,
      class: el.className.substring(0, 40),
      text: el.textContent.trim().substring(0, 40),
      color: s.color,
      backgroundColor: s.backgroundColor,
      fontSize: s.fontSize,
      fontWeight: s.fontWeight,
      opacity: s.opacity
    };
  });
}"

function: "() => {
  function luminance(r, g, b) {
    const [rs, gs, bs] = [r/255, g/255, b/255].map(c =>
      c <= 0.03928 ? c/12.92 : Math.pow((c+0.055)/1.055, 2.4));
    return 0.2126*rs + 0.7152*gs + 0.0722*bs;
  }
  function parseColor(str) {
    const m = str.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    return m ? [+m[1], +m[2], +m[3]] : [0,0,0];
  }
  function contrast(fg, bg) {
    const l1 = luminance(...fg), l2 = luminance(...bg);
    const [lighter, darker] = l1 > l2 ? [l1, l2] : [l2, l1];
    return (lighter + 0.05) / (darker + 0.05);
  }

  const results = [];
  document.querySelectorAll('h1,h2,h3,h4,p,span,a,button,li,td,th,label,.badge').forEach(el => {
    const s = getComputedStyle(el);
    const fg = parseColor(s.color);
    const bg = parseColor(s.backgroundColor);
    const ratio = contrast(fg, bg);
    if (ratio < 4.5) {
      results.push({
        text: el.textContent.trim().substring(0, 30),
        fg: s.color, bg: s.backgroundColor,
        ratio: ratio.toFixed(2),
        passesAA: ratio >= 4.5
      });
    }
  });
  return results;
}"
